from lab import *
import random

def make_folds(seed, k=5):
    f = sorted(set(fams.tolist())); random.Random(seed).shuffle(f)
    m = {x: i % k for i, x in enumerate(f)}
    return np.array([m[x] for x in fams.tolist()])

FOLDSETS = [make_folds(s) for s in (0, 1, 2, 3)]
X, labels = rank.pair_features(F, zsel, sel, aux, bm, length)
cand = rank.candidates(base)
Xc = rank.gather(X, cand)
Yc = np.take_along_axis(Rel, cand, 1)

def gb_params(obj='lambdarank', leaves=8, lr=0.05, mdl=20, ff=0.7, l2=5.0, seed=0):
    p = {"objective": obj, "learning_rate": lr, "num_leaves": leaves, "min_data_in_leaf": mdl, "feature_fraction": ff, "bagging_fraction": 0.8,
         "bagging_freq": 1, "lambda_l2": l2, "max_bin": 63, "num_threads": 2, "verbosity": -1, "seed": seed, "deterministic": True, "force_row_wise": True}
    if obj == 'lambdarank':
        p.update({"metric": "ndcg", "eval_at": [3], "lambdarank_truncation_level": 10})
    return p

def cv_gb(cols, rounds=80, folds_list=FOLDSETS, **kw):
    res = []
    for folds_ in folds_list:
        out = np.zeros(n)
        for f in sorted(set(folds_.tolist())):
            tr, va = np.where(folds_ != f)[0], np.where(folds_ == f)[0]
            keep = tr[Yc[tr].any(1)]
            Xt = Xc[keep][:, :, cols]
            ds = lgb.Dataset(Xt.reshape(-1, len(cols)), label=Yc[keep].astype(int).reshape(-1), group=[Xc.shape[1]] * len(keep))
            b = lgb.train(gb_params(**kw), ds, num_boost_round=rounds)
            s = b.predict(Xc[va][:, :, cols].reshape(-1, len(cols)), raw_score=True).reshape(len(va), -1)
            full = np.full((len(va), N), -1e9); np.put_along_axis(full, cand[va], s, axis=1)
            out[va] = hyb.case_metric(full, Rel[va])[0]
        res.append(out)
    return np.mean([r.mean() for r in res]), np.mean(res, axis=0)

def cv_graph_m(method, folds_list=FOLDSETS):
    res = []
    for fo in folds_list:
        o, a, ch = rank.cv_graph(method, base, Rel, fo, aux)
        res.append(o)
    return np.mean([r.mean() for r in res]), np.mean(res, axis=0)

def cv_wz(folds_list=FOLDSETS):
    res = []
    for fo in folds_list:
        o, a = hyb.cross_validate('wz', F, Rel, fo, sel, w)
        res.append(o)
    return np.mean([r.mean() for r in res]), np.mean(res, axis=0)

if __name__ == '__main__':
    allc = list(range(len(labels)))
    t = time.time()
    r_wz = cv_wz(); print('wz', round(r_wz[0], 4), sty(r_wz[1]))
    for m in ('prf', 'sm', 'prfsm', 'csls'):
        r = cv_graph_m(m); print(m, round(r[0], 4), sty(r[1]))
    r = cv_gb(allc); print('gbdt all', round(r[0], 4), sty(r[1]), round(time.time() - t))
    print(labels)

