def sig(z): return 1 / (1 + np.exp(-z))
tri_peak = tri.max(1)
qf = {'tri_peak': tri_peak, 'cover': cov, 'zlex_peak': F['zlex'].max(1), 'lognw': np.log(nw)}
def gate_score(x, wmax, c, s, idx=slice(None)):
    wq = wmax * sig((x[idx] - c) / s)
    return F['zens'][idx] + wq[:, None] * F['zlex'][idx]

def cv_gate(name, folds_list=FOLDSETS, sign=1):
    x = qf[name] * sign
    qs_ = np.quantile(x, [0.2, 0.35, 0.5, 0.65, 0.8])
    sd = x.std()
    grid = [(wm, c, s * sd) for wm in (0.1, 0.2, 0.3, 0.5, 0.8) for c in qs_ for s in (0.15, 0.5)]
    res = []; chosen = []
    for fo in folds_list:
        out = np.zeros(n)
        for f in sorted(set(fo.tolist())):
            tr, va = np.where(fo != f)[0], np.where(fo == f)[0]
            best = max(grid, key=lambda g: hyb.case_metric(gate_score(x, *g, idx=tr), Rel[tr])[0].mean())
            chosen.append(best)
            out[va] = hyb.case_metric(gate_score(x, *best, idx=va), Rel[va])[0]
        res.append(out)
    return np.mean([r.mean() for r in res]), np.mean(res, axis=0), chosen

if __name__ == '__main__':
    for name, sign in (('tri_peak', 1), ('cover', 1), ('zlex_peak', 1), ('lognw', -1)):
        r = cv_gate(name, sign=sign)
        print(name, round(r[0], 4), sty(r[1]), r[2][:3])

