    random.Random(0).shuffle(fams)
    fold_of = {f: i % FOLDS for i, f in enumerate(fams)}
    folds = np.array([fold_of[r["family"]] for r in fit])''','''    fams = sorted({r["family"] for r in fit})

    def make_folds(seed):
        order = list(fams)
        random.Random(seed).shuffle(order)
        fold_of = {f: i % FOLDS for i, f in enumerate(order)}
        return np.array([fold_of[r["family"]] for r in fit])

    folds = make_folds(0)''')
old=s[s.index('        per, accs, cv = {}, {}, {}'):s.index('        report["cv_seconds"] = round(time.time() - T0, 2)')]
new='''        per, accs, cv = {}, {}, {}
        seed_cv = {m: [] for m in ("ens",) + METHODS}
        for m in ("ens",) + METHODS:
            ps, as_ = [], []
            for sd in CV_SEEDS:
                p_, a_ = hyb.cross_validate(m, F, Rel, make_folds(sd), sel_names, sel_w)
                ps.append(p_)
                as_.append(a_)
                seed_cv[m].append(round(float(p_.mean()), 4))
            per[m], accs[m] = np.mean(ps, axis=0), np.mean(as_, axis=0)      # усреднение по повторам CV (по запросам)
            cv[m] = float(per[m].mean())
        report["cv"] = {m: round(v, 4) for m, v in cv.items()}
        report["cv_per_seed"] = seed_cv
        report["acc1_cv"] = {m: round(float(accs[m].mean()), 4) for m in per}
        report["cv_by_style"] = {m: by_style(per[m], styles) for m in per}
        report["acc1_by_style"] = {m: by_style(accs[m], styles) for m in per}
        report["paired_vs_ens"] = {m: pair(per[m], per["ens"]) for m in METHODS}
        report["paired_vs_wz"] = {m: pair(per[m], per["wz"]) for m in METHODS if m != "wz"}
        tpk = F["tpk"]
        report["tri_peak_by_style"] = {s_: round(float(tpk[styles == s_].mean()), 3) for s_ in sorted(set(styles.tolist()))}
        if no_overlap.any():
            report["no_overlap_acc1"] = {m: round(float(accs[m][no_overlap].mean()), 4) for m in per}
'''
s=s.replace(old,new)
s=s.replace('''            report["in_sample_selected"]''','''            report["in_sample_selected"]''')
open('build.py','w').write(s)
E
