print(sys.argv[2], 'score', sum(v[0] for v in B.values()) / 200, 'acc1', sum(v[4]['acc1'] for v in B.values()) / 200, 'np3', sum(v[4]['np3'] for v in B.values()) / 200)
print(sys.argv[1], 'score', sum(v[0] for v in A.values()) / 200)
bet = sum(B[k][0] > A[k][0] + 1e-9 for k in A); wor = sum(B[k][0] < A[k][0] - 1e-9 for k in A)
print('better/worse', bet, wor, 'same top3', sum(A[k][1] == B[k][1] for k in A), 'same top1', sum(A[k][1][0] == B[k][1][0] for k in A))
st = collections.defaultdict(list)
for k in A: st[meta[k]['style']].append((A[k][0], B[k][0]))
for s, v in sorted(st.items()): print(s, len(v), round(sum(a for a, b in v) / len(v), 3), '->', round(sum(b for a, b in v) / len(v), 3))
fam = collections.defaultdict(list)
for k in A: fam[meta[k]['family']].append(B[k][0] - A[k][0])
fl = list(fam); rs = random.Random(0); bs = []
for _ in range(4000):
    pick = [fl[rs.randrange(len(fl))] for _ in fl]
    vals = [x for f in pick for x in fam[f]]
    bs.append(sum(vals) / len(vals))
bs.sort(); print('cluster bootstrap CI', round(bs[100], 4), round(bs[3900], 4))
ts = [v[3] for v in B.values()]
print('solve s median %.2f mean %.2f max %.2f' % (statistics.median(ts), statistics.mean(ts), max(ts)))
for k in A:
    if A[k][0] != B[k][0]:
        print(round(B[k][0] - A[k][0], 2), meta[k]['style'][:4], '|', json.load(open(R+'r8-01-curve.json'))['examples'][0]['input'][:0], k)

